import { Component, OnInit, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { CatalogueService } from '../catalogue.service';
import { Product } from '../models';
@Component({standalone:true,imports:[RouterLink],template:`
<section class="hero"><div class="container hero-grid"><div><span class="eyebrow">WATER SOLUTIONS CATALOGUE</span><h1>Find the right water solution for <em>your space.</em></h1><p class="lead-copy">Explore products by brand and category in one simple catalogue.</p><a routerLink="/catalogue" class="btn btn-brand btn-lg mt-3">Browse catalogue →</a><p class="hero-small mt-4">Simple browsing · Clear product details · Mobile friendly</p></div><div class="hero-art"><div class="drop"><span>PURE<br>WATER</span></div><div class="float-card">Explore<br><small>Multiple brands</small></div></div></div></section>
<section class="section"><div class="container"><div class="section-title"><div><small>START EXPLORING</small><h2>Browse by brand</h2></div><a routerLink="/catalogue">View all products →</a></div><div class="row g-3 mb-5">@for (brand of brandCards; track brand.slug) {<div class="col-12 col-md-4"><a class="brand-tile" [routerLink]="['/catalogue']" [queryParams]="{brand:brand.slug}"><b>{{brand.symbol}}</b><span><strong>{{brand.name}}</strong><small>{{brand.caption}}</small></span><i>↗</i></a></div>}</div>
<div class="section-title"><div><small>FEATURED</small><h2>Featured products</h2></div><a routerLink="/catalogue">Explore all →</a></div>
@if(loading){<p class="text-center py-5">Loading catalogue…</p>} @else if(error){<div class="alert alert-warning">{{error}}</div>} @else if(products.length===0){<div class="empty">No featured products yet. Browse the catalogue to see all demo records.</div>} @else {<div class="row g-4">@for(p of products;track p.id){<div class="col-12 col-sm-6 col-lg-4"><article class="product-card"><a [routerLink]="['/product',p.slug]"><img [src]="p.image_url" [alt]="p.name"></a><div class="p-3"><small class="meta">{{p.brand.name}} · {{p.category.name}}</small><h3><a [routerLink]="['/product',p.slug]">{{p.name}}</a></h3><p>{{p.description}}</p><div class="d-flex justify-content-between border-top pt-3"><b>{{p.mrp===null?'Price on request':('MRP ₹'+p.mrp)}}</b><a [routerLink]="['/product',p.slug]">Details ↗</a></div></div></article></div>}</div>}</div></section>
<section class="cta"><div class="container d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><h2>All your catalogue browsing, in one place.</h2><a routerLink="/catalogue" class="btn btn-light btn-lg">Explore products →</a></div></section>`})
export class HomeComponent implements OnInit {
 private api=inject(CatalogueService); products:Product[]=[]; loading=true; error='';
 brandCards=[{name:'Aakash AquaTech',slug:'aakash-aquatech',caption:'Company catalogue',symbol:'A'},{name:'KENT',slug:'kent',caption:'Brand catalogue',symbol:'K'},{name:'Aquaguard',slug:'aquaguard',caption:'Brand catalogue',symbol:'Q'}];
 ngOnInit(){this.api.getProducts({featured:true}).subscribe({next:x=>{this.products=x;this.loading=false;},error:()=>{this.error='Could not load products. Start the FastAPI backend first.';this.loading=false;}});}
}
