import { Component, OnInit, inject } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { CatalogueService } from '../catalogue.service';
import { Product } from '../models';

@Component({
  standalone: true,
  imports: [RouterLink],
  template: `
    <section class="page-banner">
      <div class="container">
        <a routerLink="/catalogue" class="back-link">
          ← Back to Catalogue
        </a>

        <small class="d-block mt-3">PRODUCT DETAILS</small>
        <h1>{{ product?.name || 'Product Details' }}</h1>
        <p>Discover product features and contact us for enquiries.</p>
      </div>
    </section>

    <section class="section">
      <div class="container">
        @if (loading) {
          <div class="text-center py-5">
            <p>Loading product details...</p>
          </div>
        } @else if (error) {
          <div class="alert alert-warning">
            {{ error }}
          </div>

          <a routerLink="/catalogue" class="btn btn-outline-brand">
            Browse Catalogue
          </a>
        } @else if (product) {
          <div class="row g-4 align-items-start">
            <div class="col-12 col-md-6">
              <div class="product-detail-image-wrapper">
                <img
                  [src]="product.image_url"
                  [alt]="product.name"
                  class="product-detail-image"
                />
              </div>
            </div>

            <div class="col-12 col-md-6 product-detail-info">
              <small class="meta">
                {{ product.brand.name }} · {{ product.category.name }}
              </small>

              <h2 class="mt-3">{{ product.name }}</h2>

              <p class="product-model">
                <strong>Model Number:</strong>
                {{ product.model_number }}
              </p>

              <p class="product-description">
                {{ product.description }}
              </p>

              <div class="product-detail-price">
                @if (product.mrp === null) {
                  <span>Price on request</span>
                } @else {
                  <span>MRP ₹{{ product.mrp }}</span>
                }
              </div>

              <div class="product-detail-actions">
                <a
                  [href]="whatsappLink"
                  target="_blank"
                  rel="noopener noreferrer"
                  class="btn btn-success"
                >
                  Enquire on WhatsApp
                </a>

                <a
                  routerLink="/catalogue"
                  class="btn btn-outline-brand"
                >
                  ← Back to Catalogue
                </a>
              </div>

              <div class="product-note mt-4">
                <strong>Need assistance?</strong>
                <p>
                  Contact our team for product availability, pricing,
                  installation, and service information.
                </p>
              </div>
            </div>
          </div>
        }
      </div>
    </section>
  `
})
export class ProductDetailComponent implements OnInit {
  private route = inject(ActivatedRoute);
  private api = inject(CatalogueService);

  product: Product | null = null;
  loading = true;
  error = '';
  whatsappLink = '';

  ngOnInit(): void {
    this.route.paramMap.subscribe((params) => {
      const slug = params.get('slug');

      if (!slug) {
        this.error = 'Product not found.';
        this.loading = false;
        return;
      }

      this.loading = true;
      this.error = '';
      this.product = null;

      this.api.getProduct(slug).subscribe({
        next: (data) => {
          this.product = data;

          const message = encodeURIComponent(
            `Hello AquaTech, I am interested in ${data.name} (Model: ${data.model_number}). Please share more details.`
          );

          // Replace with your business WhatsApp number.
          const whatsappNumber = '91XXXXXXXXXX';

          this.whatsappLink =
            `https://wa.me/${whatsappNumber}?text=${message}`;

          this.loading = false;
        },
        error: (err) => {
          console.error('Product loading failed:', err);
          this.error = 'Unable to load this product. Please try again.';
          this.loading = false;
        }
      });
    });
  }
}